#### 1523\. 在区间范围内统计奇数数目
(https://leetcode.cn/problems/count-odd-numbers-in-an-interval-range/) 很简单，没必要前缀和
```cpp
// B3693 数列前缀和 4 // 2026-04-22 00:13:05 // 2026-04-22 00:49:31 38 min
using u64 = unsigned long long;

// 模板代码
class NumMatrix {
	vector<vector<u64>> sum;
  public:
	NumMatrix(vector<vector<u64>>& matrix) {
		int m = matrix.size();
		int n = m == 0 ? 0 : matrix[0].size();
		sum.resize(m + 1, vector<u64>(n + 1, 0));
		for(int i = 0; i < m; i++) {
			for(int j = 0; j < n; j++) {
				sum[i + 1][j + 1] = sum[i + 1][j] + sum[i][j + 1] - sum[i][j] + matrix[i][j];
			}
		}
	}
	u64 sumRegion(int r1, int c1, int r2, int c2) {
		return sum[r2 + 1][c2 + 1] - sum[r2 + 1][c1] - sum[r1][c2 + 1] + sum[r1][c1];
	}
};

int main() {
	int T;
	cin >> T;
	while(T--) {
		int n, m, q;
		cin >> n >> m >> q;
		vector<vector<u64>> matrix(n, vector<u64>(m));
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				cin >> matrix[i][j];
			}
		}
		NumMatrix nm(matrix);
		u64 xorSum = 0;
		while(q--) {
			int u, v, x, y;
			cin >> u >> v >> x >> y;
			// 转换为 0-indexed（因为类内部用 0-indexed 计算）
			u--;
			v--;
			x--;
			y--;
			u64 ans = nm.sumRegion(u, v, x, y);
			xorSum ^= ans;
		}
		cout << xorSum << '\n';
	}
	return 0;
}
```
- 题目中要求计算结果对 2 的 64 次方取余（注意 `2e64` 表示 `2*10^64`）
- ull 的最大值+1 刚好是取余的大小，所以**不用取余**，ull 的一旦溢出之后的数字就等于取余后的结果（注意**一定要 ull**才会不会有符号变化问题）

